"""Opaque downloads selected only from persisted native task artifacts."""

import hashlib
import os
import re
from pathlib import Path

from fastapi import Depends, FastAPI, HTTPException
from fastapi.responses import FileResponse
from src.api.mona_reads import _private_file
from src.api.security import require_auth
from src.api.swarm_routes import _get_swarm_runtime


def _artifacts(run_id: str):
    if not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", run_id):
        raise HTTPException(status_code=404, detail="Swarm run not found")
    store = _get_swarm_runtime()._store
    run = store.load_run(run_id)
    if run is None:
        raise HTTPException(status_code=404, detail="Swarm run not found")
    root = store.run_dir(run_id).resolve()
    result = []
    for task in run.tasks:
        for relative in task.artifacts:
            if not isinstance(relative, str):
                continue
            artifact_id = hashlib.sha256((task.id + "\0" + relative).encode()).hexdigest()
            try:
                path = _private_file(root / relative)
                if not path.is_relative_to(root):
                    continue
            except HTTPException:
                continue
            result.append((artifact_id, task.id, path))
    return result


def register_mona_swarm_artifacts(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    @app.get("/mona/swarm-runs/{run_id}/artifacts", dependencies=[Depends(require_auth)])
    async def list_artifacts(run_id: str):
        items = []
        for artifact_id, task_id, path in _artifacts(run_id):
            size = path.stat().st_size
            digest = hashlib.sha256(path.read_bytes()).hexdigest() if size <= 16 * 1024 * 1024 else None
            items.append({"artifact_id": artifact_id, "task_id": task_id, "filename": path.name,
                          "bytes": size, "sha256": digest})
        return {"artifacts": items}

    @app.get("/mona/swarm-runs/{run_id}/artifacts/{artifact_id}", dependencies=[Depends(require_auth)])
    async def download_artifact(run_id: str, artifact_id: str):
        if not re.fullmatch(r"[a-f0-9]{64}", artifact_id):
            raise HTTPException(status_code=404, detail="Artifact not found")
        for found, _task, path in _artifacts(run_id):
            if found == artifact_id:
                return FileResponse(path, filename=Path(path).name, content_disposition_type="attachment")
        raise HTTPException(status_code=404, detail="Artifact not found")
